CREATE TABLE "EconomyAccount" ("guildId" TEXT NOT NULL,"memberId" TEXT NOT NULL,"optedIn" BOOLEAN NOT NULL DEFAULT false,"optRequestId" TEXT,"balance" INTEGER NOT NULL DEFAULT 0 CHECK("balance" BETWEEN 0 AND 1000000),"lastDailyAt" TIMESTAMP(3),"lastPlayedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EconomyAccount_pkey" PRIMARY KEY("guildId","memberId"));
CREATE TABLE "EconomyEntry" ("id" TEXT NOT NULL,"guildId" TEXT NOT NULL,"memberId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"kind" TEXT NOT NULL CHECK("kind" IN ('DAILY','COIN','BUY','ADJUST','TRADE')),"fingerprint" TEXT NOT NULL,"delta" INTEGER NOT NULL CHECK("delta" BETWEEN -1000000 AND 1000000),"balanceAfter" INTEGER NOT NULL CHECK("balanceAfter" BETWEEN 0 AND 1000000),"reason" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EconomyEntry_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "EconomyEntry_guildId_requestId_key" ON "EconomyEntry"("guildId","requestId");
CREATE INDEX "EconomyEntry_guildId_memberId_createdAt_idx" ON "EconomyEntry"("guildId","memberId","createdAt");
CREATE INDEX "EconomyEntry_createdAt_idx" ON "EconomyEntry"("createdAt");
CREATE TABLE "EconomyInventory" ("guildId" TEXT NOT NULL,"memberId" TEXT NOT NULL,"itemId" TEXT NOT NULL,"quantity" INTEGER NOT NULL DEFAULT 0 CHECK("quantity" BETWEEN 0 AND 99),CONSTRAINT "EconomyInventory_pkey" PRIMARY KEY("guildId","memberId","itemId"),CONSTRAINT "EconomyInventory_account_fkey" FOREIGN KEY("guildId","memberId") REFERENCES "EconomyAccount"("guildId","memberId") ON DELETE CASCADE);
CREATE INDEX "EconomyEntry_guildId_actorId_createdAt_idx" ON "EconomyEntry"("guildId","actorId","createdAt");
